const GLOBAL_CSS = `
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500&family=Italiana&family=Marcellus&family=Jost:wght@300;400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap');
* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
body { margin: 0; }
.hq { font-family: 'Jost', system-ui, sans-serif; font-weight: 400; }
.hq-mono { font-family: 'IBM Plex Mono', monospace; }
.hq-fade { animation: hqFade .4s ease both; }
.hq-press { transition: transform .15s ease, box-shadow .15s ease; }
.hq-press:active { transform: scale(.97); }
@keyframes hqFade { from { opacity: 0; transform: translateY(8px);} to { opacity: 1; transform: none;} }
@media (prefers-reduced-motion: reduce) { .hq-fade { animation: none; } }
.lux-rule { height: 1px; border: none; background: linear-gradient(90deg, transparent, var(--metal-mid, #C6A15B), transparent); }
.hq-ad { position: relative; overflow: hidden; }
.hq-ad::after { content: ""; position: absolute; top: 0; left: -60%; width: 40%; height: 100%; background: linear-gradient(105deg, transparent, rgba(255,255,255,.32), transparent); animation: hqSheen 2.8s ease-in-out infinite; }
@keyframes hqSheen { 0% { left: -60%; } 55% { left: 130%; } 100% { left: 130%; } }
@media (prefers-reduced-motion: reduce) { .hq-ad::after { animation: none; display: none; } }
button { font-family: inherit; cursor: pointer; }
input, select, textarea { font-family: inherit; }
input:focus, select:focus, textarea:focus, button:focus-visible { outline: 1.5px solid var(--focus, #C6A15B); outline-offset: 2px; }
/* Unified toolbar — bottom bar on phones, left rail on desktop */
.hq-nav { position: fixed; bottom: 0; left: 0; right: 0; z-index: 40; }
.hq-nav-inner { max-width: 560px; margin: 0 auto; display: flex; }
.hq-nav-inner button + button { border-left: 1.5px solid rgba(0,0,0,.16); }
@media (min-width: 900px) {
  .hq-nav { top: 0; right: auto; bottom: 0; width: 132px; border-top: none !important; border-right: 1px solid var(--nav-accent, #C6A15B); }
  .hq-nav-inner { flex-direction: column; max-width: none; height: 100%; justify-content: flex-start; padding-top: 30px; }
  .hq-nav-inner button { flex: 0 0 auto !important; padding: 19px 0 !important; border-top: none !important; border-bottom: 1.5px solid rgba(0,0,0,.16); }
  .hq-nav-inner button + button { border-left: none; }
  .hq-nav-inner button:last-child { border-bottom: none; }
  .hq-nav-inner button span { font-size: 11.5px !important; }
  .hq-body { margin-left: 132px; }
  main { max-width: 640px !important; }
}
/* ---------- refinements ---------- */
.hq { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; text-rendering: optimizeLegibility; }
.hq-mono { font-variant-numeric: tabular-nums; font-feature-settings: "tnum"; }
::selection { background: rgba(198,161,91,.26); }
html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }

/* lists that arrive one after another instead of all at once */
.hq-stagger > * { animation: hqFade .42s ease both; }
.hq-stagger > *:nth-child(1) { animation-delay: .02s }
.hq-stagger > *:nth-child(2) { animation-delay: .06s }
.hq-stagger > *:nth-child(3) { animation-delay: .10s }
.hq-stagger > *:nth-child(4) { animation-delay: .14s }
.hq-stagger > *:nth-child(5) { animation-delay: .18s }
.hq-stagger > *:nth-child(6) { animation-delay: .22s }
.hq-stagger > *:nth-child(n+7) { animation-delay: .26s }
@media (prefers-reduced-motion: reduce) { .hq-stagger > * { animation: none; } }

/* something to look at while data loads */
.hq-skel { position: relative; overflow: hidden; background: rgba(20,17,14,.055); border-radius: 7px; }
.hq-skel::after { content: ""; position: absolute; inset: 0; transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.55), transparent); animation: hqSkel 1.4s infinite; }
@keyframes hqSkel { 100% { transform: translateX(100%); } }
@media (prefers-reduced-motion: reduce) { .hq-skel::after { animation: none; } }

/* one place for confirmations, instead of five different inline messages */
.hq-toast-wrap { position: fixed; left: 0; right: 0; bottom: 84px; z-index: 120; display: flex; flex-direction: column;
  align-items: center; gap: 7px; pointer-events: none; padding: 0 16px; }
@media (min-width: 900px) { .hq-toast-wrap { bottom: 26px; left: 132px; } }
.hq-toast { pointer-events: auto; max-width: 400px; width: fit-content; display: flex; align-items: center; gap: 9px;
  padding: 11px 17px; border-radius: 999px; background: rgba(24,21,18,.94); color: #F6F1E8;
  font-family: 'IBM Plex Mono', monospace; font-size: 9.5px; letter-spacing: 1.6px; font-weight: 500;
  box-shadow: 0 6px 22px rgba(20,15,10,.30); animation: hqToast .3s ease both; backdrop-filter: blur(6px); }
@keyframes hqToast { from { opacity: 0; transform: translateY(10px) scale(.96); } to { opacity: 1; transform: none; } }
.hq-toast.out { animation: hqToastOut .28s ease both; }
@keyframes hqToastOut { to { opacity: 0; transform: translateY(6px) scale(.97); } }
@media (prefers-reduced-motion: reduce) { .hq-toast, .hq-toast.out { animation: none; } }

/* lift on hover where there's a pointer to hover with */
@media (hover: hover) {
  .hq-press:hover { transform: translateY(-1px); }
  .hq-press:active { transform: scale(.97); }
}

/* quieter scrollbars on desktop */
@media (min-width: 900px) {
  ::-webkit-scrollbar { width: 9px; height: 9px; }
  ::-webkit-scrollbar-thumb { background: rgba(20,17,14,.16); border-radius: 9px; }
  ::-webkit-scrollbar-track { background: transparent; }
}

/* a line of news that drifts past above the hero */
.hq-ticker { overflow: hidden; position: relative; -webkit-mask-image: linear-gradient(90deg, transparent, #000 9%, #000 91%, transparent);
  mask-image: linear-gradient(90deg, transparent, #000 9%, #000 91%, transparent); }
.hq-ticker-track { display: inline-flex; align-items: center; gap: 34px; white-space: nowrap; will-change: transform;
  animation: hqTick var(--tick, 34s) linear infinite; }
.hq-ticker:hover .hq-ticker-track { animation-play-state: paused; }
@keyframes hqTick { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@media (prefers-reduced-motion: reduce) { .hq-ticker-track { animation: none; } .hq-ticker { mask-image: none; -webkit-mask-image: none; } }

/* the bit that has to shout */
.hq-live { position: relative; display: inline-flex; align-items: center; gap: 5px; padding: 2px 9px 2px 7px; border-radius: 999px;
  background: linear-gradient(95deg, #0E7C80, #12939A 45%, #6EC1D6); color: #FFFFFF; font-weight: 700; letter-spacing: 2px; }
.hq-live::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: #FFFFFF; animation: hqPulse 1.5s ease-in-out infinite; }
@keyframes hqPulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: .35; transform: scale(.7); } }
@media (prefers-reduced-motion: reduce) { .hq-live::before { animation: none; } }

/* day headings that stay put while a long list scrolls under them */
.hq-daystick { position: sticky; top: 46px; z-index: 12; }

/* print: drop the furniture */
@media print {
  .hq-nav, .hq-toast-wrap, .hq-press { display: none !important; }
  .hq-body { margin-left: 0 !important; }
}
`;

