/* ---------- confirmations ---------- */
const toast = (text, tone) => {
  try { window.dispatchEvent(new CustomEvent("hq-toast", { detail: { text, tone } })); } catch {}
};

function ToastHost() {
  const [items, setItems] = useState([]);
  useEffect(() => {
    const on = (e) => {
      const id = "t" + Date.now() + Math.random();
      setItems((v) => [...v, { id, text: e.detail.text, tone: e.detail.tone }]);
      setTimeout(() => setItems((v) => v.map((i) => (i.id === id ? { ...i, out: true } : i))), 2600);
      setTimeout(() => setItems((v) => v.filter((i) => i.id !== id)), 2950);
    };
    window.addEventListener("hq-toast", on);
    return () => window.removeEventListener("hq-toast", on);
  }, []);
  if (!items.length) return null;
  return (
    <div className="hq-toast-wrap">
      {items.map((i) => (
        <div key={i.id} className={"hq-toast" + (i.out ? " out" : "")}>
          <span style={{ color: i.tone === "bad" ? "#E6A99A" : "#D9BC93", fontSize: 11 }}>
            {i.tone === "bad" ? "!" : "✓"}
          </span>
          {String(i.text).toUpperCase()}
        </div>
      ))}
    </div>
  );
}

