/* a headshot, cropped square and kept small enough to travel in a request */
const compressAvatar = (file) => new Promise((resolve, reject) => {
  const img = new Image(); const url = URL.createObjectURL(file);
  img.onload = () => {
    const side = Math.min(img.width, img.height);
    const sx = (img.width - side) / 2, sy = (img.height - side) / 2;
    const c = document.createElement("canvas");
    c.width = 260; c.height = 260;
    c.getContext("2d").drawImage(img, sx, sy, side, side, 0, 0, 260, 260);
    URL.revokeObjectURL(url);
    resolve(c.toDataURL("image/jpeg", 0.6).split(",")[1]);
  };
  img.onerror = () => { URL.revokeObjectURL(url); reject(new Error("Could not read image")); };
  img.src = url;
});

const compressImage = (file) => new Promise((resolve, reject) => {
  const img = new Image(); const url = URL.createObjectURL(file);
  img.onload = () => {
    const s = Math.min(1, 1100 / Math.max(img.width, img.height));
    const c = document.createElement("canvas");
    c.width = Math.round(img.width * s); c.height = Math.round(img.height * s);
    c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
    URL.revokeObjectURL(url);
    resolve(c.toDataURL("image/jpeg", 0.72).split(",")[1]);
  };
  img.onerror = () => { URL.revokeObjectURL(url); reject(new Error("Could not read image")); };
  img.src = url;
});

const askClaude = async (messages, maxTokens = 1000) => {
  const res = await fetch("/api/paige", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model: "claude-sonnet-4-6", max_tokens: maxTokens, messages }),
  });
  const data = await res.json();
  if (data.error) throw new Error(data.error.message || "AI request failed");
  return data.content.map((b) => (b.type === "text" ? b.text : "")).filter(Boolean).join("\n");
};

const BIZ_CONTEXT = `The owner (Paige) runs THREE 1099 businesses in Lexington, KY:
1. "RE" — Real estate: Paige is a REALTOR® with ERA Select Real Estate (commission income). Deductions: marketing, signage, MLS and license dues, client gifts, showing mileage, staging.
2. "PP" — Pageant Perfect by Paige: pageant coaching (interview, walk, stage). Lessons in a home studio/garage. Tue–Fri 11am–8pm. Services $35–$135.
3. "VG" — Velvet Glow: luxury custom airbrush spray tanning, home studio, occasional on-location group tans. Mon–Fri 10am–10pm. Services $35–$100+.
She ALSO directs her own pageant, Miss Kentucky's Queen, collecting entry fees and concessions and paying event expenses.
Shared home studio space; some expenses may be split (supplies, home studio, mileage).`;

const analyzeReceipt = async (base64) => {
  const text = await askClaude([{
    role: "user",
    content: [
      { type: "image", source: { type: "base64", media_type: "image/jpeg", data: base64 } },
      { type: "text", text: `${BIZ_CONTEXT}

Read this receipt image. Respond with ONLY a JSON object, no markdown fences, no preamble:
{"vendor": string, "date": "YYYY-MM-DD or empty", "amount": number, "category": short expense category, "biz": "RE" | "PP" | "VG" | "Personal", "deductible": "likely" | "possibly" | "unlikely", "note": one sentence on why, tied to the specific business, "tip": one practical tip}
Marketing/signage/MLS dues/client gifts/staging → RE; spray tan solution/equipment → VG; pageant entry fees, coaching materials, crowns/sashes, directed-pageant event costs → PP. If it serves several, pick the better fit and say so in the note. Not business-related → biz "Personal", deductible "unlikely". Not a receipt → vendor "Unknown", amount 0, deductible "unlikely".` },
    ],
  }]);
  return JSON.parse(text.replace(/```json|```/g, "").trim());
};

/* ================= .ics + CSV ================= */
const pad = (n) => String(n).padStart(2, "0");
const icsStamp = () => { const d = new Date(); return `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}T${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}00Z`; };
const esc = (s) => String(s || "").replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\n/g, "\\n");
const vevent = (ev) => {
  const uid = `hq-${Math.random().toString(36).slice(2)}@paigehq`;
  let when;
  if (ev.time) {
    const [y, m, d] = ev.date.split("-").map(Number);
    const [hh, mm] = ev.time.split(":").map(Number);
    const start = new Date(y, m - 1, d, hh, mm);
    const end = new Date(start.getTime() + (ev.durMin || 60) * 60000);
    const fmt = (x) => `${x.getFullYear()}${pad(x.getMonth() + 1)}${pad(x.getDate())}T${pad(x.getHours())}${pad(x.getMinutes())}00`;
    when = `DTSTART:${fmt(start)}\nDTEND:${fmt(end)}`;
  } else {
    const dt = ev.date.replace(/-/g, "");
    when = `DTSTART;VALUE=DATE:${dt}\nDTEND;VALUE=DATE:${dt}`;
  }
  return `BEGIN:VEVENT\nUID:${uid}\nDTSTAMP:${icsStamp()}\n${when}\nSUMMARY:${esc(ev.title)}${ev.location ? `\nLOCATION:${esc(ev.location)}` : ""}${ev.notes ? `\nDESCRIPTION:${esc(ev.notes)}` : ""}\nEND:VEVENT`;
};
const downloadFile = (filename, text, mime) => {
  const blob = new Blob([text], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename; a.click();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
};
const downloadICS = (filename, events) =>
  downloadFile(filename, `BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//PaigeHQ//EN\nCALSCALE:GREGORIAN\n${events.map(vevent).join("\n")}\nEND:VCALENDAR`, "text/calendar;charset=utf-8");

const csvCell = (v) => `"${String(v ?? "").replace(/"/g, '""')}"`;
const exportBooksCSV = (receipts, income, mileage, rate, directing) => {
  const rows = [["Type", "Business", "Date", "Description", "Category", "Amount", "Deductible", "Notes"]];
  receipts.forEach((r) => rows.push(["Expense", r.biz, r.date, r.vendor, r.category, (r.amount || 0).toFixed(2), r.deductible, r.note]));
  income.forEach((i) => rows.push(["Income", i.biz, i.date, i.source, i.method || "", (i.amount || 0).toFixed(2), "", i.notes || ""]));
  mileage.forEach((m) => rows.push(["Mileage", m.biz, m.date, m.purpose, `${m.miles} miles @ $${rate}/mi`, (m.miles * rate).toFixed(2), "likely", ""]));
  (directing || []).forEach((d) => {
    (d.entries || []).forEach((e) => rows.push(["Directing income", d.name, "", `Entry fee — ${e.name}`, e.division || "", (e.fee || 0).toFixed(2), "", e.paid ? "paid" : "unpaid"]));
    (d.income || []).forEach((i) => rows.push(["Directing income", d.name, i.date, i.desc, "", (i.amount || 0).toFixed(2), "", ""]));
    (d.expenses || []).forEach((x) => rows.push(["Directing expense", d.name, x.date, x.desc, "", (x.amount || 0).toFixed(2), "likely", ""]));
  });
  downloadFile(`paige-books-${new Date().toISOString().slice(0, 10)}.csv`, rows.map((r) => r.map(csvCell).join(",")).join("\n"), "text/csv;charset=utf-8");
};

