/* ---------------- push notifications ---------------- */
const VAPID_PUBLIC = import.meta.env.VITE_VAPID_PUBLIC_KEY || "";

const urlB64ToUint8 = (b64) => {
  const pad = "=".repeat((4 - (b64.length % 4)) % 4);
  const raw = atob((b64 + pad).replace(/-/g, "+").replace(/_/g, "/"));
  return Uint8Array.from([...raw].map((c) => c.charCodeAt(0)));
};

const pushSupported = () =>
  typeof window !== "undefined" && "serviceWorker" in navigator && "PushManager" in window && !!VAPID_PUBLIC;

async function pushStatus() {
  if (!pushSupported()) return "unsupported";
  if (Notification.permission === "denied") return "blocked";
  try {
    const reg = await navigator.serviceWorker.getRegistration();
    const sub = reg && (await reg.pushManager.getSubscription());
    return sub ? "on" : "off";
  } catch { return "off"; }
}

async function pushEnable() {
  if (!pushSupported()) throw new Error("This device can't do notifications");
  const perm = await Notification.requestPermission();
  if (perm !== "granted") throw new Error("Notifications were turned down");
  const reg = await navigator.serviceWorker.register("/sw.js");
  await navigator.serviceWorker.ready;
  let sub = await reg.pushManager.getSubscription();
  if (!sub) {
    sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: urlB64ToUint8(VAPID_PUBLIC) });
  }
  const r = await fetch("/api/push", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ action: "save", sub: sub.toJSON(), label: navigator.userAgent.slice(0, 60) }),
  });
  const j = await r.json();
  if (!j.ok) throw new Error(j.error || "Couldn't turn them on");
  return true;
}

async function pushDisable() {
  const reg = await navigator.serviceWorker.getRegistration();
  const sub = reg && (await reg.pushManager.getSubscription());
  if (sub) {
    await fetch("/api/push", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "remove", endpoint: sub.endpoint }),
    });
    await sub.unsubscribe();
  }
  return true;
}

/* fire-and-forget: tell her something landed */
const pingPaige = (kind) => {
  try {
    fetch("/api/push", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "notify", kind }),
    }).catch(() => {});
  } catch {}
};

/* ================= MKQ LIVE COUNTDOWN (shared by both portals) ================= */
function useMkqCountdown() {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    let id = null;
    const start = () => { stop(); id = setInterval(() => setNow(Date.now()), 1000); };
    const stop = () => { if (id) clearInterval(id); id = null; };
    /* no point counting seconds against a hidden tab — it just burns battery */
    const onVis = () => (document.hidden ? stop() : (setNow(Date.now()), start()));
    start();
    document.addEventListener("visibilitychange", onVis);
    return () => { stop(); document.removeEventListener("visibilitychange", onVis); };
  }, []);
  const diff = Math.max(0, new Date("2026-10-03T00:00:00").getTime() - now);
  return { diff, d: Math.floor(diff / 86400000), h: Math.floor(diff / 3600000) % 24, m: Math.floor(diff / 60000) % 60, s: Math.floor(diff / 1000) % 60 };
}

