/* ================= GALLERY (client-facing) ================= */
function GalleryPage({ B, lock }) {
  const { card } = useBrandBits(B);
  const [view, setView] = useState(lock === "pp" ? "wins" : "glows");
  const [items, setItems] = useState([]);
  const [imgs, setImgs] = useState({});

  useEffect(() => {
    (async () => {
      const idx = (await loadJSON("gallery")) || [];
      setItems(idx);
      const map = {};
      for (const it of idx) {
        for (const key of ["before", "after", "photo"]) {
          if (it[key + "Id"]) {
            const d = await loadJSON("gallery-img:" + it[key + "Id"]);
            if (d) map[it[key + "Id"]] = d;
          }
        }
      }
      setImgs(map);
    })();
  }, []);

  const glows = items.filter((i) => i.kind === "glow" && i.pub !== false);
  const wins = items.filter((i) => i.kind === "win");
  const shown = view === "glows" ? glows : wins;
  const br = view === "glows" ? BRANDS.vg : BRANDS.pp;
  const pic = (id) => (imgs[id] ? `data:image/jpeg;base64,${imgs[id]}` : null);

  return (
    <div className="hq-fade">
      {!lock && <div style={{ display: "flex", gap: 7, marginBottom: 14 }}>
        {[["glows", "✦ BEFORE & AFTER"], ["wins", "♛ WALL OF FAME"]].map(([v, lab]) => {
          const on = view === v;
          const b2 = v === "glows" ? BRANDS.vg : BRANDS.pp;
          return (
            <button key={v} onClick={() => setView(v)} className="hq-mono hq-press"
              style={{ flex: 1, padding: "10px 4px", borderRadius: 5, fontSize: 8.5, letterSpacing: 1.5, fontWeight: 700, cursor: "pointer",
                border: `1px solid ${on ? b2.c.deep : B.c.line}`, background: on ? b2.c.deep : "#FFFFFF", color: on ? b2.c.gold : B.c.ink }}>
              {lab}
            </button>
          );
        })}
      </div>}

      {lock && (
        <div className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 2.5, color: br.c.accent, fontWeight: 700, marginBottom: 12 }}>
          {view === "glows" ? "✦ BEFORE & AFTER" : "♛ WALL OF FAME"}
        </div>
      )}

      {shown.length === 0 && (
        <Empty B={B} mark={view === "glows" ? "✦" : "♛"}
          title={view === "glows" ? "Fresh glows coming soon" : "Crowns are coming"}
          body={view === "glows"
            ? "Paige is adding her latest work — check back in a few days."
            : "This is where her girls land after a win. Somebody has to be first."} />
      )}

      {/* Before & after pairs */}
      {view === "glows" && glows.map((g) => (
        <div key={g.id} style={{ ...card, padding: 10, marginBottom: 12, overflow: "hidden" }}>
          <div style={{ display: "flex", gap: 6 }}>
            {[["before", "BEFORE"], ["after", "AFTER"]].map(([k, lab]) => (
              <div key={k} style={{ flex: 1, position: "relative", borderRadius: 6, overflow: "hidden", background: B.c.soft }}>
                {pic(g[k + "Id"])
                  ? <img src={pic(g[k + "Id"])} alt={lab} loading="lazy" decoding="async" style={{ width: "100%", height: 210, objectFit: "cover", display: "block" }} />
                  : <div style={{ height: 210 }} />}
                <span className="hq-mono" style={{ position: "absolute", left: 7, top: 7, padding: "3px 8px", borderRadius: 3, background: "rgba(20,17,14,.72)", color: "#FBF8F3", fontSize: 7, letterSpacing: 1.5, fontWeight: 600 }}>{lab}</span>
              </div>
            ))}
          </div>
          {(g.caption || g.shade) && (
            <div style={{ padding: "9px 4px 2px" }}>
              {g.caption && <div style={{ fontSize: 13, fontWeight: 300, color: B.c.ink, lineHeight: 1.5 }}>{g.caption}</div>}
              {g.shade && <div className="hq-mono" style={{ fontSize: 7.5, letterSpacing: 1.5, color: BRANDS.vg.c.accent, marginTop: 3 }}>{g.shade.toUpperCase()}</div>}
            </div>
          )}
        </div>
      ))}

      {/* Wall of fame */}
      {view === "wins" && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 10 }}>
          {wins.map((w) => (
            <div key={w.id} style={{ borderRadius: 10, overflow: "hidden", background: `linear-gradient(160deg, ${BRANDS.pp.c.deep} 20%, ${BRANDS.pp.c.deep2} 100%)`, boxShadow: "0 3px 12px rgba(20,15,10,.20)" }}>
              {pic(w.photoId) && <img src={pic(w.photoId)} alt={w.name} loading="lazy" decoding="async" style={{ width: "100%", height: 190, objectFit: "cover", objectPosition: "50% 22%", display: "block" }} />}
              <div style={{ padding: "10px 11px 12px", textAlign: "center" }}>
                <div style={{ fontFamily: BRANDS.pp.display, fontSize: 15, fontWeight: 600, color: BRANDS.pp.c.gold, lineHeight: 1.15 }}>♛ {w.name}</div>
                <div style={{ fontSize: 11.5, fontWeight: 300, color: BRANDS.pp.c.soft, marginTop: 4, lineHeight: 1.45 }}>{w.title}</div>
                {w.date && <div className="hq-mono" style={{ fontSize: 7, letterSpacing: 1.5, color: BRANDS.pp.c.gold, opacity: 0.7, marginTop: 5 }}>{w.date.replace(/-/g, ".")}</div>}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ================= MKQ PUBLIC (client-facing) ================= */
function MkqPublic({ B, settings = {} }) {
  const cd = useMkqCountdown();
  const open = !!settings.mkqOpen;
  const [form, setForm] = useState({ name: "", age: "", division: "", parent: "", phone: "", email: "" });
  const [busy, setBusy] = useState(false);
  const [sent, setSent] = useState(false);
  const ok = form.name.trim() && form.phone.trim();

  const submit = async () => {
    if (!ok) return;
    setBusy(true);
    const note = [
      `Contestant: ${form.name.trim()}`,
      form.age ? `Age ${form.age}` : "",
      form.division ? `Division: ${form.division}` : "",
      form.parent ? `Parent: ${form.parent}` : "",
      form.email ? `Email: ${form.email}` : "",
    ].filter(Boolean).join(" · ");
    const done = await sendRequest({ name: form.name.trim(), phone: form.phone.trim(), brand: "PP", kind: "mkq", note });
    setBusy(false);
    if (done) { pingPaige("request"); setSent(true); }
  };

  const field = (key, label, type) => (
    <div style={{ marginBottom: 9 }}>
      <div className="hq-mono" style={{ fontSize: 7.5, letterSpacing: 1.5, color: "#7FA9B4", marginBottom: 4 }}>{label.toUpperCase()}</div>
      <input type={type || "text"} value={form[key]} onChange={(e) => setForm({ ...form, [key]: e.target.value })}
        style={{ width: "100%", padding: "12px 13px", fontSize: 15, border: "1px solid rgba(255,255,255,.22)", borderRadius: 6,
          background: "rgba(255,255,255,.06)", color: "#EAF6F8", boxSizing: "border-box" }} />
    </div>
  );

  return (
    <div className="hq-fade">
      <div style={{ background: "linear-gradient(165deg, #06070A 12%, #0F1418 100%)", borderRadius: 12, padding: "18px 16px 16px", marginBottom: 12, textAlign: "center", boxShadow: "0 4px 16px rgba(0,0,0,.30)" }}>
        <img src={MKQ_LOGO} alt="Miss Kentucky's Queen" style={{ width: "86%", maxWidth: 320, display: "block", margin: "0 auto" }} />
        {open && (
          <div style={{ marginTop: 13 }}>
            <span className="hq-mono hq-live" style={{ fontSize: 10, padding: "6px 15px 6px 11px" }}>REGISTRATION IS NOW LIVE</span>
          </div>
        )}
      </div>

      <div style={{ position: "relative", borderRadius: 12, overflow: "hidden", boxShadow: "0 4px 16px rgba(0,0,0,.32)", marginBottom: 14 }}>
        <img src={MKQ_POSTER} alt="Miss Kentucky's Queen — October 3, 2026" style={{ width: "100%", display: "block" }} />
        <CountdownPill cd={cd} />
      </div>

      <div style={{ background: B.c.card, border: `1px solid ${B.c.line}`, borderRadius: 8, padding: "16px 18px", textAlign: "center", marginBottom: 12 }}>
        <div style={{ fontFamily: B.display, fontSize: 20, fontWeight: 600, letterSpacing: 1 }}>♛ Miss Kentucky's Queen</div>
        <div className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 2, color: B.c.faint, margin: "6px 0 10px" }}>
          OCTOBER 3, 2026 · DIRECTED BY PAIGE HENDERSON &amp; CHANDRA HORNBACK
        </div>
        <p style={{ fontSize: 13.5, fontWeight: 300, lineHeight: 1.7, margin: 0 }}>
          {settings.mkqBlurb ||
            (open
              ? "Registration is open. Put your name down below and we'll be in touch with the packet, divisions and fees."
              : "Entry details, divisions and venue announced soon — watch this page. Ask Coach Paige at your next lesson to get your name on the list early.")}
        </p>
      </div>

      {/* Entry form */}
      <div style={{ padding: "17px 18px", borderRadius: 12,
        background: `linear-gradient(160deg, ${B.c.deep} 20%, ${B.c.deep2} 100%)`, boxShadow: "0 4px 16px rgba(0,0,0,.26)" }}>
        {sent ? (
          <div style={{ textAlign: "center", padding: "10px 0" }}>
            <div style={{ fontSize: 24, color: B.c.gold }}>♛</div>
            <div style={{ fontFamily: B.display, fontSize: 19, fontWeight: 600, color: "#FFFFFF", marginTop: 8 }}>You're on the list</div>
            <p style={{ fontSize: 13, fontWeight: 300, color: B.c.soft, opacity: 0.9, lineHeight: 1.7, margin: "7px 0 0" }}>
              Paige or Chandra will reach out with everything you need. See you October 3rd.
            </p>
          </div>
        ) : (
          <>
            <div className="hq-mono" style={{ fontSize: 8, letterSpacing: 3, color: B.c.gold, marginBottom: 4 }}>
              {open ? "ENTER THE PAGEANT" : "GET ON THE LIST EARLY"}
            </div>
            <p style={{ fontSize: 12.5, fontWeight: 300, color: B.c.soft, opacity: 0.85, lineHeight: 1.6, margin: "0 0 13px" }}>
              {open
                ? "Fill this in and we'll send the entry packet."
                : "Not an entry yet — just tells us you're interested, and you'll hear first when registration opens."}
            </p>
            {field("name", "Contestant's name")}
            <div style={{ display: "flex", gap: 9 }}>
              <div style={{ flex: 0.7 }}>{field("age", "Age", "number")}</div>
              <div style={{ flex: 1.3 }}>{field("division", "Division, if you know it")}</div>
            </div>
            {field("parent", "Parent or guardian")}
            {field("phone", "Phone", "tel")}
            {field("email", "Email", "email")}
            <button onClick={submit} disabled={!ok || busy} className="hq-press"
              style={{ width: "100%", marginTop: 4, padding: 15, borderRadius: 7, border: "none", cursor: "pointer",
                background: ok && !busy ? B.c.metal : "rgba(255,255,255,.18)",
                color: ok && !busy ? B.c.deep : "rgba(255,255,255,.55)", fontSize: 11, letterSpacing: 2.5, fontWeight: 700 }}>
              {busy ? "SENDING…" : open ? "REQUEST MY ENTRY PACKET" : "KEEP ME POSTED"}
            </button>
            <p className="hq-mono" style={{ fontSize: 6.5, letterSpacing: 1.2, color: B.c.soft, opacity: 0.55, textAlign: "center", marginTop: 10, lineHeight: 1.8 }}>
              A PARENT SHOULD FILL THIS IN FOR ANYONE UNDER 18
            </p>
          </>
        )}
      </div>
    </div>
  );
}

