/* ---------- year-end packet: opens a clean printable page ---------- */
function buildPacket({ year, income, index, mileage, settings }) {
  const rate = Number(settings.mileRate) || 0.7;
  const inYear = (d) => String(d || "").startsWith(String(year));
  const inc = income.filter((i) => inYear(i.date));
  const exp = index.filter((r) => inYear(r.date));
  const mi = mileage.filter((m) => inYear(m.date));

  const bizName = { PP: "Pageant Perfect", VG: "Velvet Glow", RE: "Real Estate" };
  const incomeBy = {};
  inc.forEach((i) => { incomeBy[i.biz || "Other"] = (incomeBy[i.biz || "Other"] || 0) + (i.amount || 0); });

  const expBy = {};
  exp.forEach((r) => {
    const k = r.category || "Uncategorised";
    if (!expBy[k]) expBy[k] = { total: 0, count: 0, likely: 0, maybe: 0 };
    expBy[k].total += r.amount || 0;
    expBy[k].count += 1;
    if (r.deductible === "likely") expBy[k].likely += r.amount || 0;
    if (r.deductible === "possibly") expBy[k].maybe += r.amount || 0;
  });

  const miles = mi.reduce((s, m) => s + (m.miles || 0), 0);
  const totalIn = inc.reduce((s, i) => s + (i.amount || 0), 0);
  const totalExp = exp.reduce((s, r) => s + (r.amount || 0), 0);
  const mileDed = miles * rate;

  const row = (a, b, bold) =>
    `<tr${bold ? ' class="b"' : ""}><td>${a}</td><td class="n">${b}</td></tr>`;
  const money2 = (n) => "$" + (Math.round(n * 100) / 100).toLocaleString("en-US", { minimumFractionDigits: 2 });

  return `<!doctype html><html><head><meta charset="utf-8"><title>Paige HQ — ${year} Summary</title>
<style>
  body{font-family:Georgia,'Times New Roman',serif;color:#1e1c19;max-width:760px;margin:36px auto;padding:0 24px;line-height:1.55}
  h1{font-size:26px;letter-spacing:1px;margin:0 0 4px;font-weight:normal}
  .sub{font-family:ui-monospace,Menlo,monospace;font-size:10px;letter-spacing:2px;color:#8a8378;margin-bottom:26px}
  h2{font-size:13px;letter-spacing:2.5px;font-family:ui-monospace,Menlo,monospace;color:#8a8378;margin:30px 0 8px;font-weight:normal;text-transform:uppercase}
  table{width:100%;border-collapse:collapse;font-size:14px}
  td{padding:7px 0;border-bottom:1px solid #eae5dc}
  td.n{text-align:right;font-family:ui-monospace,Menlo,monospace;white-space:nowrap}
  tr.b td{font-weight:bold;border-bottom:2px solid #1e1c19;border-top:1px solid #1e1c19}
  .note{font-size:11.5px;color:#8a8378;margin-top:8px;line-height:1.7}
  .foot{margin-top:38px;padding-top:14px;border-top:1px solid #eae5dc;font-size:11px;color:#8a8378}
  @media print{body{margin:0}}
</style></head><body>
<h1>Paige Swope-Henderson</h1>
<div class="sub">${year} BUSINESS SUMMARY · PAGEANT PERFECT · VELVET GLOW</div>

<h2>Income received</h2>
<table>
${Object.entries(incomeBy).map(([k, v]) => row(bizName[k] || k, money2(v))).join("")}
${row("Total income", money2(totalIn), true)}
</table>
<div class="note">${inc.length} payment${inc.length === 1 ? "" : "s"} recorded.</div>

<h2>Expenses by category</h2>
<table>
${Object.entries(expBy).sort((a, b) => b[1].total - a[1].total)
  .map(([k, v]) => row(`${k} <span style="color:#8a8378;font-size:12px">(${v.count})</span>`, money2(v.total))).join("")}
${row("Total receipts", money2(totalExp), true)}
</table>
<div class="note">
  Flagged likely deductible: ${money2(Object.values(expBy).reduce((s, v) => s + v.likely, 0))} ·
  worth a conversation: ${money2(Object.values(expBy).reduce((s, v) => s + v.maybe, 0))}.
</div>

<h2>Mileage</h2>
<table>
${row("Business miles driven", miles.toLocaleString("en-US"))}
${row(`At $${rate}/mile`, money2(mileDed), true)}
</table>

<h2>Rough picture</h2>
<table>
${row("Income", money2(totalIn))}
${row("Receipts", "(" + money2(totalExp) + ")")}
${row("Mileage", "(" + money2(mileDed) + ")")}
${row("Left over", money2(totalIn - totalExp - mileDed), true)}
</table>

<div class="foot">
  Prepared from Paige HQ on ${new Date().toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })}.
  Figures come from what was logged in the app and are a starting point for your accountant, not tax advice.
  Receipt images are stored in the app and can be exported separately.
</div>
</body></html>`;
}

/* ================= INCOME TRENDS (live analytics) ================= */
function IncomeTrends({ B, income, index = [], mileage = [], settings = {} }) {
  const { card, H } = useBrandBits(B);
  const now = new Date();
  const year = String(now.getFullYear());
  const ym = `${year}-${pad(now.getMonth() + 1)}`;
  const monthName = now.toLocaleDateString("en-US", { month: "long" });

  const sumBy = (pred, b) => income.filter((i) => pred(i) && (b ? i.biz === b : true)).reduce((s, i) => s + (i.amount || 0), 0);
  const inMonth = (i) => (i.date || "").startsWith(ym);
  const inYear = (i) => (i.date || "").startsWith(year);
  const monthly = Array.from({ length: 12 }, (_, m) => sumBy((i) => (i.date || "").startsWith(`${year}-${pad(m + 1)}`)));

  /* what it cost to earn it */
  const spent = (pred) => index.filter((r) => pred(r) && r.deductible !== "no").reduce((s, r) => s + (r.amount || 0), 0);
  const rate = Number(settings.mileRate) || 0.7;
  const miles = (pred) => mileage.filter(pred).reduce((s, m) => s + (m.miles || 0), 0);
  const monthSpend = spent(inMonth) + miles(inMonth) * rate;
  const yearSpend = spent(inYear) + miles(inYear) * rate;
  const byService = {};
  income.filter(inYear).forEach((i) => {
    const key = (i.service || "").trim();
    if (!key) return;
    if (!byService[key]) byService[key] = { total: 0, count: 0 };
    byService[key].total += i.amount || 0;
    byService[key].count += 1;
  });
  const topServices = Object.entries(byService).sort((a, b) => b[1].total - a[1].total).slice(0, 6);

  /* what an hour of her time is actually worth, per business */
  const perHour = ["VG", "PP"].map((code) => {
    const rows = income.filter((i) => inYear(i) && i.biz === code);
    const total = rows.reduce((s, i) => s + (i.amount || 0), 0);
    const mins = rows.reduce((s, i) => {
      const m = Number(i.durMin) || 0;
      if (m) return s + m;
      return s + (code === "VG" ? 30 : 60);          // sensible default per session
    }, 0);
    return { code, label: code === "VG" ? "✦ Tanning" : "♛ Coaching", total, hours: mins / 60, rate: mins ? total / (mins / 60) : 0 };
  }).filter((p) => p.total > 0);
  const tipsYear = income.filter(inYear).reduce((s, i) => s + (i.tip || 0), 0);
  const monthEarned = sumBy(inMonth);
  const yearEarned = sumBy(inYear);
  const maxM = Math.max(...monthly, 1);
  const letters = ["J", "F", "M", "A", "M", "J", "J", "A", "S", "O", "N", "D"];

  const PeriodCard = ({ label, pred }) => {
    const rows = [["♛ Pageant Perfect", sumBy(pred, "PP"), BRANDS.pp.c.accent], ["✦ Velvet Glow", sumBy(pred, "VG"), BRANDS.vg.c.accent], ["◈ Realty", sumBy(pred, "RE"), BRANDS.re.c.accent]];
    const total = rows.reduce((s, r) => s + r[1], 0);
    return (
      <div style={{ ...card, padding: "14px 16px", marginBottom: 12 }}>
        <div className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 2.5, color: B.c.accent, marginBottom: 9, fontWeight: 500 }}>{label}</div>
        {rows.map(([lab, v, col]) => (
          <div key={lab} style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", padding: "4px 0" }}>
            <span style={{ fontSize: 13.5, fontWeight: 300 }}><span style={{ color: col }}>{lab.slice(0, 1)}</span>{lab.slice(1)}</span>
            <span className="hq-mono" style={{ fontSize: 13, fontWeight: 500 }}>{money(v)}</span>
          </div>
        ))}
        <hr className="lux-rule" style={{ margin: "7px 0" }} />
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
          <span className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.faint }}>TOTAL</span>
          <span className="hq-mono" style={{ fontSize: 16, fontWeight: 500, color: "#4E6B4E" }}>{money(total)}</span>
        </div>
      </div>
    );
  };

  return (
    <div className="hq-fade">
      <PeriodCard label={`THIS MONTH · ${monthName.toUpperCase()} ${year}`} pred={inMonth} />
      <PeriodCard label={`THIS YEAR · ${year}`} pred={inYear} />

      {/* What's actually left */}
      <div style={{ padding: "15px 17px", borderRadius: 10, marginBottom: 12,
        background: `linear-gradient(160deg, ${B.c.deep} 15%, ${B.c.deep2} 100%)`, boxShadow: "0 4px 14px rgba(20,15,10,.20)" }}>
        <div className="hq-mono" style={{ fontSize: 8, letterSpacing: 2.5, color: B.c.gold, opacity: 0.8, marginBottom: 10 }}>WHAT'S LEFT AFTER EXPENSES</div>
        {[["This month", monthEarned, monthSpend], ["This year", yearEarned, yearSpend]].map(([lab, earned, out]) => (
          <div key={lab} style={{ marginBottom: lab === "This month" ? 11 : 0 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
              <span style={{ fontSize: 13.5, fontWeight: 300, color: B.c.soft }}>{lab}</span>
              <span className="hq-mono" style={{ fontSize: 17, fontWeight: 500, color: earned - out >= 0 ? B.c.gold : "#E6A99A" }}>{money(earned - out)}</span>
            </div>
            <div className="hq-mono" style={{ fontSize: 7.5, letterSpacing: 1.2, color: B.c.soft, opacity: 0.6, marginTop: 3 }}>
              {money(earned)} IN · {money(out)} OUT
            </div>
          </div>
        ))}
        <p className="hq-mono" style={{ fontSize: 6.5, letterSpacing: 1, color: B.c.soft, opacity: 0.55, marginTop: 11, lineHeight: 1.8 }}>
          EXPENSES INCLUDE MILEAGE AT ${rate}/MI. AN ESTIMATE, NOT TAX ADVICE.
        </p>
      </div>

      {/* what an hour is worth */}
      {perHour.length > 0 && (
        <div style={{ ...card, padding: "14px 16px", marginBottom: 12 }}>
          <div className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 2.5, color: B.c.accent, marginBottom: 10, fontWeight: 500 }}>WHAT AN HOUR IS WORTH · {year}</div>
          {perHour.map((p) => (
            <div key={p.code} style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", padding: "6px 0", borderBottom: `1px solid ${B.c.line}` }}>
              <div>
                <div style={{ fontSize: 13.5, fontWeight: 400 }}>{p.label}</div>
                <div className="hq-mono" style={{ fontSize: 7, letterSpacing: 1, color: B.c.faint, marginTop: 2 }}>
                  {money(p.total)} OVER {Math.round(p.hours)} HOURS
                </div>
              </div>
              <span className="hq-mono" style={{ fontSize: 16, fontWeight: 500, color: B.c.ink, whiteSpace: "nowrap" }}>{money(p.rate)}<span style={{ fontSize: 9, color: B.c.faint }}>/hr</span></span>
            </div>
          ))}
          <p className="hq-mono" style={{ fontSize: 6.5, letterSpacing: 1, color: B.c.faint, marginTop: 9, lineHeight: 1.8 }}>
            CHAIR TIME ONLY — DRIVING, PREP AND CLEANUP AREN'T COUNTED.
          </p>
        </div>
      )}

      {/* what sells */}
      {topServices.length > 0 && (
        <div style={{ ...card, padding: "14px 16px", marginBottom: 12 }}>
          <div className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 2.5, color: B.c.accent, marginBottom: 10, fontWeight: 500 }}>WHAT SELLS · {year}</div>
          {topServices.map(([name, v]) => (
            <div key={name} style={{ marginBottom: 8 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 10 }}>
                <span style={{ fontSize: 13, fontWeight: 300, minWidth: 0 }}>{name}</span>
                <span className="hq-mono" style={{ fontSize: 12.5, fontWeight: 500, whiteSpace: "nowrap" }}>{money(v.total)}</span>
              </div>
              <div style={{ height: 4, borderRadius: 2, background: B.c.soft, marginTop: 4, overflow: "hidden" }}>
                <div style={{ width: `${Math.round((v.total / topServices[0][1].total) * 100)}%`, height: "100%", background: B.c.accent, borderRadius: 2 }} />
              </div>
              <div className="hq-mono" style={{ fontSize: 6.5, letterSpacing: 1, color: B.c.faint, marginTop: 3 }}>
                {v.count} SOLD · {money(v.total / v.count)} AVERAGE
              </div>
            </div>
          ))}
          {tipsYear > 0 && (
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", paddingTop: 9, marginTop: 4, borderTop: `1px solid ${B.c.line}` }}>
              <span className="hq-mono" style={{ fontSize: 8, letterSpacing: 2, color: B.c.faint }}>TIPS THIS YEAR</span>
              <span className="hq-mono" style={{ fontSize: 13, fontWeight: 500, color: "#4E6B4E" }}>{money(tipsYear)}</span>
            </div>
          )}
        </div>
      )}

      <div style={{ ...card, padding: "14px 16px" }}>
        <div className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 2.5, color: B.c.accent, marginBottom: 12, fontWeight: 500 }}>INCOME BY MONTH · {year}</div>
        <div style={{ display: "flex", alignItems: "flex-end", gap: 4, height: 92 }}>
          {monthly.map((v, m) => (
            <div key={m} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 3, height: "100%", justifyContent: "flex-end" }}>
              {v > 0 && <div className="hq-mono" style={{ fontSize: 6, color: B.c.faint, whiteSpace: "nowrap" }}>{v >= 1000 ? `${Math.round(v / 100) / 10}k` : Math.round(v)}</div>}
              <div style={{ width: "100%", borderRadius: "3px 3px 0 0", height: Math.max(3, Math.round((v / maxM) * 64)), background: m === now.getMonth() ? B.c.accent : v > 0 ? (B.c.accent2 || B.c.rose) : B.c.line, opacity: m === now.getMonth() ? 1 : 0.75 }} />
              <div className="hq-mono" style={{ fontSize: 7, color: m === now.getMonth() ? B.c.accent : B.c.faint, fontWeight: m === now.getMonth() ? 600 : 400 }}>{letters[m]}</div>
            </div>
          ))}
        </div>
        <p style={{ fontSize: 11, fontWeight: 300, color: B.c.faint, margin: "10px 0 0" }}>Live from everything logged under Income — updates the moment a payout is recorded.</p>
      </div>
    </div>
  );
}

/* ================= ADVISOR ================= */
function AdvisorTab({ B, index, pageants, clients, income, mileage, settings, directing, estate }) {
  const { input, H } = useBrandBits(B);
  const [msgs, setMsgs] = useState([]);
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const bottomRef = useRef(null);
  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: "smooth" }); }, [msgs, busy]);

  const context = () => {
    const sums = {};
    index.forEach((r) => { const k = `${r.biz}:${r.category}`; sums[k] = (sums[k] || 0) + (r.amount || 0); });
    const incSums = { RE: 0, PP: 0, VG: 0 };
    income.forEach((i) => { incSums[i.biz] = (incSums[i.biz] || 0) + (i.amount || 0); });
    const miles = { RE: 0, PP: 0, VG: 0 };
    mileage.forEach((m) => { miles[m.biz] = (miles[m.biz] || 0) + m.miles; });
    const dir = directing.map((d) => ({
      name: d.name,
      feesPaid: (d.entries || []).reduce((s, e) => s + (e.paid ? e.fee || 0 : 0), 0),
      otherIncome: (d.income || []).reduce((s, i) => s + (i.amount || 0), 0),
      expenses: (d.expenses || []).reduce((s, x) => s + (x.amount || 0), 0),
      contestants: (d.entries || []).length,
    }));
    return `${BIZ_CONTEXT}
You are the in-app tax and business guide. Be warm, practical, concise (under 150 words unless asked for depth). The three businesses are separate 1099 activities — note when an expense belongs on one Schedule C vs another or should be split; directed-pageant income (entry fees, concessions) is also self-employment income to report. You are not a CPA; say so on high-stakes questions and recommend a professional for filings.
Expense totals by business:category → ${JSON.stringify(sums)}
Income totals → ${JSON.stringify(incSums)}. Mileage → ${JSON.stringify(miles)} miles at $${settings.mileRate}/mi.
Directed pageants → ${JSON.stringify(dir)}
Receipts: ${index.length}. Pageants tracked: ${pageants.length}. Clients: ${clients.length}. Portfolio items: ${estate.length}.`;
  };

  const send = async () => {
    const q = text.trim();
    if (!q || busy) return;
    const next = [...msgs, { role: "user", content: q }];
    setMsgs(next); setText(""); setBusy(true);
    try {
      const reply = await askClaude([
        { role: "user", content: context() },
        { role: "assistant", content: "Understood — I'll answer as Paige's in-app guide with that context." },
        ...next,
      ], 1000);
      setMsgs([...next, { role: "assistant", content: reply }]);
    } catch {
      setMsgs([...next, { role: "assistant", content: "That didn't go through — check your connection and try again." }]);
    } finally { setBusy(false); }
  };

  const starters = [
    "How are the books looking across all three businesses?",
    "What can I write off as a realtor?",
    "How do I report Miss Kentucky's Queen income?",
    "Can I deduct part of the house for the garage studio?",
  ];

  return (
    <div className="hq-fade" style={{ display: "flex", flexDirection: "column", minHeight: "60vh" }}>
      <div style={{ flex: 1 }}>
        {msgs.length === 0 && (
          <div style={{ textAlign: "center", paddingTop: 12 }}>
            <H>The Advisor</H>
            <p style={{ color: B.c.faint, fontSize: 13.5, fontWeight: 300, lineHeight: 1.6 }}>Knows all three businesses, the directed pageant, every receipt, the income, and the miles.</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 8, marginTop: 10 }}>
              {starters.map((s) => (
                <button key={s} onClick={() => setText(s)} style={{ padding: "11px 14px", borderRadius: 4, border: `1px solid ${B.c.line}`, background: B.c.card, fontSize: 13.5, fontWeight: 300, color: B.c.ink }}>{s}</button>
              ))}
            </div>
          </div>
        )}
        {msgs.map((m, i) => (
          <div key={i} style={{ display: "flex", justifyContent: m.role === "user" ? "flex-end" : "flex-start", marginBottom: 10 }}>
            <div style={{
              maxWidth: "86%", padding: "12px 15px", fontSize: 14.5, lineHeight: 1.6, whiteSpace: "pre-wrap", fontWeight: m.role === "user" ? 400 : 300,
              borderRadius: 6, background: m.role === "user" ? B.c.deep : B.c.card, color: m.role === "user" ? B.c.soft : B.c.ink,
              border: m.role === "user" ? "none" : `1px solid ${B.c.line}`,
            }}>{m.content}</div>
          </div>
        ))}
        {busy && <div className="hq-mono" style={{ fontSize: 9.5, letterSpacing: 3, color: B.c.faint }}>COMPOSING…</div>}
        <div ref={bottomRef} />
      </div>
      <div style={{ display: "flex", gap: 8, marginTop: 12, position: "sticky", bottom: 84 }}>
        <input style={{ ...input, flex: 1 }} value={text} placeholder="Ask a question…" onChange={(e) => setText(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()} />
        <button onClick={send} disabled={busy || !text.trim()}
          style={{ padding: "0 20px", borderRadius: 4, border: "none", background: busy || !text.trim() ? "#C9C4BA" : B.c.deep, color: B.c.gold, fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Send</button>
      </div>
      <p style={{ fontSize: 10.5, fontWeight: 300, color: B.c.faint, textAlign: "center", marginTop: 10 }}>
        AI guidance for planning only — confirm anything important with a CPA before filing.
      </p>
    </div>
  );
}
